static ssize_t set_a_bus_drop ( struct device * dev , struct device_attribute * attr , const char * buf , size_t count ) { struct mv_otg * mvotg = dev_get_drvdata ( dev ) ; if ( ! mvotg -> phy . otg -> default_a ) { return - 1 ; } if ( buf [ 0 ] == '0' ) { mvotg -> otg_ctrl . a_bus_drop = 0 ; dev_dbg ( & mvotg -> pdev -> dev , "User request: a_bus_drop = 0\n" ) ; } if ( buf [ 0 ] == '1' ) { mvotg -> otg_ctrl . a_bus_drop = 1 ; mvotg -> otg_ctrl . a_bus_req = 0 ; dev_dbg ( & mvotg -> pdev -> dev , "User request: a_bus_drop = 1\n" ) ; dev_dbg ( & mvotg -> pdev -> dev , "User request: and a_bus_req = 0\n" ) ; } if ( spin_trylock ( & mvotg -> wq_lock ) ) { mv_otg_run_state_machine ( mvotg , 0 ) ; spin_unlock ( & mvotg -> wq_lock ) ; } return count ; } 